mapper.update:
UPDATE execution_runs
SET used_model_rounds=used_model_rounds+1,updated_at=#{startedAt}
WHERE run_id=#{runId} AND plan_id=#{planId} AND plan_revision_id=#{planRevisionId}
  AND status IN ('RUNNING','VERIFYING')
  AND pause_requested=0
  AND max_model_rounds IS NOT NULL AND used_model_rounds < max_model_rounds
  AND wall_budget_millis IS NOT NULL AND used_active_millis < wall_budget_millis
  AND EXISTS (
        SELECT 1 FROM plans p
        WHERE p.plan_id=execution_runs.plan_id
          AND p.plan_id=#{planId}
          AND p.owner_thread_id=#{ownerThreadId}
          AND p.status='VERIFYING'
          AND p.active_run_id=execution_runs.run_id
          AND p.active_plan_revision_id=execution_runs.plan_revision_id
  )

UPDATE execution_runs
SET used_active_millis=used_active_millis + (
        SELECT CAST(MAX(0,ROUND((julianday(#{completedAt}) - julianday(started_at)) * 86400000.0)) AS INTEGER)
        FROM plan_evaluation_requests
        WHERE request_id=#{requestId} AND plan_id=#{planId}
          AND plan_revision_id=#{planRevisionId} AND run_id=#{runId}
          AND outcome='RUNNING'
    ),
    updated_at=#{completedAt}
WHERE run_id=#{runId} AND plan_id=#{planId} AND plan_revision_id=#{planRevisionId}
  AND status IN ('RUNNING','VERIFYING','PAUSED','STOPPED')
  AND EXISTS (
        SELECT 1 FROM plan_evaluation_requests
        WHERE request_id=#{requestId} AND plan_id=#{planId}
          AND plan_revision_id=#{planRevisionId} AND run_id=#{runId}
          AND outcome='RUNNING'
  )

UPDATE plan_evaluation_requests SET outcome=#{outcome},certainty=#{certainty},
    input_tokens=#{inputTokens},output_tokens=#{outputTokens},total_tokens=#{totalTokens},
    verdict=#{verdict},criteria_json=#{criteriaJson},summary=#{summary},
    completed_at=#{completedAt}
WHERE request_id=#{requestId} AND plan_id=#{planId} AND plan_revision_id=#{planRevisionId}
  AND run_id=#{runId} AND outcome='RUNNING'
